    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    index = 1
    results = []

    def min_operations(n, k, a):
        if k == 2:
            # Count the number of elements that are not even
            return sum(1 for x in a if x % 2 != 0)
        elif k == 3:
            # Count the number of elements that are not divisible by 3
            return sum(1 for x in a if x % 3 != 0)
        elif k == 4:
            # Count the number of elements that are not divisible by 4
            # and the number of elements that are not divisible by 2
            count_2 = sum(1 for x in a if x % 2 != 0)
            count_4 = sum(1 for x in a if x % 4 != 0)
            return max(count_2, count_4 - count_2)
        elif k == 5:
            # Count the number of elements that are not divisible by 5
            return sum(1 for x in a if x % 5 != 0)

    for _ in range(t):
        n = int(data[index])
        k = int(data[index + 1])
        a = list(map(int, data[index + 2:index + 2 + n]))
        index += 2 + n
        results.append(min_operations(n, k, a))

