class Solution:
    def matrixSum(self, nums: List[List[int]]) -> int:
        score = 0

        while nums and all(nums[i] for i in range(len(nums))):
            max_values = [max(row) for row in nums]
            score += max(max_values)
            nums = [[num for num in row if num != max(row)] for row in nums]

        return score

