class Solution:
    def maxStrength(self, nums: List[int]) -> int:
        if len(nums) == 1:
            return nums[0]

        positive = [num for num in nums if num > 0]
        negative = sorted([num for num in nums if num < 0])

        if not positive and len(negative) <= 1 and 0 in nums:
            return 0

        product = 1
        for num in positive:
            product *= num

        for i in range(0, len(negative) - 1, 2):
            product *= negative[i] * negative[i + 1]

        if not positive and len(negative) == 1:
            return negative[0]

        return product

