class Solution:
    def count(self, num1: str, num2: str, min_sum: int, max_sum: int) -> int:
        MOD = 10**9 + 7

        def digit_sum(n: str) -> int:
            return sum(int(digit) for digit in n)

        def count_valid_numbers(n: str) -> int:
            digits = [int(d) for d in n]
            n = len(digits)

            @lru_cache(None)
            def dp(pos: int, sum: int, is_limit: bool) -> int:
                if pos == n:
                    return 1 if min_sum <= sum <= max_sum else 0

                limit = digits[pos] if is_limit else 9
                total = 0
                for d in range(limit + 1):
                    new_sum = sum + d
                    if new_sum > max_sum:
                        break
                    new_is_limit = is_limit and d == limit
                    total += dp(pos + 1, new_sum, new_is_limit)

                return total % MOD

            return dp(0, 0, True)

        count_num2 = count_valid_numbers(num2)
        count_num1_minus_1 = count_valid_numbers(str(int(num1) - 1))

        return (count_num2 - count_num1_minus_1) % MOD

