class Solution:
    def longestSemiRepetitiveSubstring(self, s: str) -> int:
        # Step 1: Identify positions of consecutive pairs
        consecutive_pairs = []
        for i in range(1, len(s)):
            if s[i] == s[i - 1]:
                consecutive_pairs.append(i)

        # Step 2: Calculate the lengths of semi-repetitive substrings
        if not consecutive_pairs:
            return len(s)  # If no consecutive pairs, the entire string is semi-repetitive

        max_length = max(consecutive_pairs[0], len(s) - consecutive_pairs[-1])

        for i in range(1, len(consecutive_pairs)):
            max_length = max(max_length, consecutive_pairs[i] - consecutive_pairs[i - 1])

        return max_length

