class Solution:
    def makeSmallestPalindrome(self, s: str) -> str:
        # Convert the string to a list to allow in-place modifications
        s_list = list(s)

        # Initialize two pointers
        left, right = 0, len(s) - 1

        # Iterate until the two pointers meet
        while left < right:
            # If the characters at the current positions are different
            if s_list[left] != s_list[right]:
                # Replace the lexicographically larger character with the smaller one
                if s_list[left] < s_list[right]:
                    s_list[right] = s_list[left]
                else:
                    s_list[left] = s_list[right]

            # Move the pointers
            left += 1
            right -= 1

        # Convert the list back to a string and return it
        return ''.join(s_list)

