class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        rootX = self.find(x)
        rootY = self.find(y)
        if rootX != rootY:
            if self.rank[rootX] > self.rank[rootY]:
                self.parent[rootY] = rootX
            elif self.rank[rootX] < self.rank[rootY]:
                self.parent[rootX] = rootY
            else:
                self.parent[rootY] = rootX
                self.rank[rootX] += 1

class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        n = len(nums)
        if n == 1:
            return True

        # Prime factorization
        prime_factors = {}
        for i, num in enumerate(nums):
            if num == 1:
                return False  # If any number is 1, it cannot be connected to any other number
            factor = 2
            while factor * factor <= num:
                if num % factor == 0:
                    if factor not in prime_factors:
                        prime_factors[factor] = []
                    prime_factors[factor].append(i)
                    while num % factor == 0:
                        num //= factor
                factor += 1
            if num > 1:
                if num not in prime_factors:
                    prime_factors[num] = []
                prime_factors[num].append(i)

        # Union-Find
        uf = UnionFind(n)
        for indices in prime_factors.values():
            for i in range(1, len(indices)):
                uf.union(indices[i - 1], indices[i])

        # Check if all indices are in the same connected component
        root = uf.find(0)
        for i in range(1, n):
            if uf.find(i) != root:
                return False
        return True

class Solution:
    def smallestString(self, s: str) -> str:
        n = len(s)
        s = list(s)  # Convert string to list for mutability

        # Find the first non-'a' character
        i = 0
        while i < n and s[i] == 'a':
            i += 1

        # If the entire string is 'a's, replace the last 'a' with 'z'
        if i == n:
            s[-1] = 'z'
        else:
            # Replace characters in the substring from the first non-'a' to the next 'a' or end of string
            while i < n and s[i] != 'a':
                s[i] = chr(ord(s[i]) - 1)
                i += 1

        return ''.join(s)

