        def first_digit(n: int) -> int:
            while n >= 10:
                n //= 10
            return n

        def last_digit(n: int) -> int:
            return n % 10

        def are_coprime(x: int, y: int) -> bool:
            return math.gcd(x, y) == 1

        count = 0
