    def makeTheIntegerZero(self, num1: int, num2: int) -> int:
        # If num1 is less than num2, it is impossible to make num1 zero
        if num1 < num2:
            return -1

        # Iterate over the number of operations k from 1 to 60
        for k in range(1, 61):
            # Calculate the target value after k operations
            target = num1 - k * num2

            # Check if the number of 1s in the binary representation of target is less than or equal to k
            # and if k is less than or equal to target
            if target >= k and bin(target).count('1') <= k:
