class Solution:
    def specialPerm(self, nums: List[int]) -> int:
        MOD = 10**9 + 7

        @lru_cache(maxsize=None)
        def count_perms(index, prev, mask):
            if index == len(nums):
                return 1

            total = 0
            for i in range(len(nums)):
                if not mask & (1 << i) and (prev == -1 or nums[i] % prev == 0 or prev % nums[i] == 0):
                    total += count_perms(index + 1, nums[i], mask | (1 << i))
                    total %= MOD

            return total

        return count_perms(0, -1, 0)

