class Solution:
    def sumImbalanceNumbers(self, nums: List[int]) -> int:
        n = len(nums)
        total_imbalance = 0

        for start in range(n):
            current_set = set()
            current_imbalance = 0
            for end in range(start, n):
                if nums[end] not in current_set:
                    # Check if the new element creates an imbalance
                    if nums[end] - 1 in current_set:
                        current_imbalance -= 1
                    if nums[end] + 1 in current_set:
                        current_imbalance -= 1
                    if nums[end] - 1 not in current_set and nums[end] + 1 not in current_set:
                        current_imbalance += 1
                    current_set.add(nums[end])
                total_imbalance += current_imbalance

        return total_imbalance

