class Solution:
    def numberOfGoodSubarraySplits(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        one_positions = [i for i, num in enumerate(nums) if num == 1]

        if not one_positions:
            return 0
        if len(one_positions) == 1:
            return 1

