    def maxArrayValue(self, nums: List[int]) -> int:
        max_val = max(nums)  # Initialize the maximum value with the largest element in the array

        i = len(nums) - 2  # Start from the second last element
        while i >= 0:
            if nums[i] <= nums[i + 1]:
                nums[i + 1] += nums[i]  # Merge nums[i] and nums[i + 1]
                del nums[i]  # Remove nums[i] from the array
