class Solution:
    def minimumChanges(self, s: str, k: int) -> int:
        from math import inf

        n = len(s)

        # Precompute the cost of converting each substring into a semi-palindrome
        def semi_palindrome_cost(sub):
            min_cost = inf
            for d in range(1, len(sub)):
                if len(sub) % d == 0:
                    cost = 0
                    for i in range(d):
                        segment = sub[i::d]
                        cost += sum(segment[j] != segment[-1-j] for j in range(len(segment) // 2))
                    min_cost = min(min_cost, cost)
            return min_cost

        # Precompute the cost for all substrings
        cost = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(i, n):
