    def countSteppingNumbers(self, low: str, high: str) -> int:
        MOD = 10**9 + 7

        def countSteppingNumbersUpTo(num: str) -> int:
            n = len(num)
            memo = {}

            def dp(pos: int, prev: int, is_tight: bool) -> int:
                if pos == n:
                    return 1
                if (pos, prev, is_tight) in memo:
                    return memo[(pos, prev, is_tight)]

                limit = int(num[pos]) if is_tight else 9
                count = 0
                for digit in range(limit + 1):
                    if pos == 0 or abs(digit - prev) == 1:
                        new_is_tight = is_tight and digit == limit
                        count += dp(pos + 1, digit, new_is_tight)

                memo[(pos, prev, is_tight)] = count % MOD
                return memo[(pos, prev, is_tight)]

            return dp(0, -1, True)

        count_high = countSteppingNumbersUpTo(high)
        count_low = countSteppingNumbersUpTo(str(int(low) - 1))

        return (count_high - count_low) % MOD

