        # Sort the adjusted_nums to use for segment tree indices
        sorted_adjusted_nums = sorted(set(adjusted_nums))

        # Segment tree to maintain the maximum dp values
        segment_tree = [0] * (4 * n)

        def update(index, value, node=1, node_left=0, node_right=len(sorted_adjusted_nums) - 1):
            if node_left == node_right:
                segment_tree[node] = max(segment_tree[node], value)
                return
            mid = (node_left + node_right) // 2
            if index <= mid:
                update(index, value, 2 * node, node_left, mid)
            else:
                update(index, value, 2 * node + 1, mid + 1, node_right)
            segment_tree[node] = max(segment_tree[2 * node], segment_tree[2 * node + 1])

