            while stack and prefix_sum[i + 1] - prefix_sum[stack[-1][0]] >= prefix_sum[stack[-1][0]] - prefix_sum[stack[-1][1]]:
                j, k = stack.pop()
                dp[i + 1] = max(dp[i + 1], dp[k] + (i - j))
            stack.append((i, i - dp[i + 1] + 1))

        return dp[n]

