class Solution:
    def lexicographicallySmallestArray(self, nums: List[int], limit: int) -> List[int]:
        # Step 1: Sort the array with their original indices
        sorted_nums = sorted((num, i) for i, num in enumerate(nums))

        # Step 2: Group elements by limit
        groups = []
        current_group = [sorted_nums[0]]
        for i in range(1, len(sorted_nums)):
            if sorted_nums[i][0] - current_group[-1][0] <= limit:
                current_group.append(sorted_nums[i])
            else:
                groups.append(current_group)
                current_group = [sorted_nums[i]]
        groups.append(current_group)

        # Step 3: Sort groups internally
        for group in groups:
            group.sort(key=lambda x: x[0])

        # Step 4: Reconstruct the array
        result = [0] * len(nums)
        for group in groups:
            sorted_values = [x[0] for x in group]
            sorted_indices = [x[1] for x in group]
            for i, idx in enumerate(sorted_indices):
                result[idx] = sorted_values[i]

        return result

