class Solution:
    def minimumCost(self, nums: List[int]) -> int:
        def is_palindrome(x):
            return str(x) == str(x)[::-1]

        def generate_palindromes():
            palindromes = []
            for i in range(1, 100000):  # Generate up to 6-digit palindromes
                s = str(i)
                palindromes.append(int(s + s[-2::-1]))  # Even length palindromes
                palindromes.append(int(s + s[::-1]))    # Odd length palindromes
            palindromes = sorted(set(palindromes))
            return [p for p in palindromes if 1 <= p <= 10**9]

        def find_closest_palindromes(median):
            idx = bisect.bisect_left(palindromes, median)
            if idx == 0:
                return [palindromes[0]]
            if idx == len(palindromes):
                return [palindromes[-1]]
            return [palindromes[idx-1], palindromes[idx]]

        def calculate_cost(p):
            return sum(abs(num - p) for num in nums)

        palindromes = generate_palindromes()
        median = sorted(nums)[len(nums) // 2]
        closest_palindromes = find_closest_palindromes(median)

        min_cost = float('inf')
        for p in closest_palindromes:
            min_cost = min(min_cost, calculate_cost(p))

        return min_cost

