class Solution:
    def minimumCost(self, source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
        # Initialize the distance matrix with infinity
        dist = [[float('inf')] * 26 for _ in range(26)]

        # Set the cost of transforming a character to itself to 0
        for i in range(26):
            dist[i][i] = 0

        # Update the distance matrix with the given transformations and costs
        for o, c, co in zip(original, changed, cost):
            o_idx = ord(o) - ord('a')
            c_idx = ord(c) - ord('a')
            dist[o_idx][c_idx] = min(dist[o_idx][c_idx], co)

        # Run the Floyd-Warshall algorithm to compute the shortest paths
        for k in range(26):
            for i in range(26):
                for j in range(26):
                    if dist[i][k] + dist[k][j] < dist[i][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

        # Calculate the total cost to transform source to target
        total_cost = 0
        for s, t in zip(source, target):
            s_idx = ord(s) - ord('a')
            t_idx = ord(t) - ord('a')
            if dist[s_idx][t_idx] == float('inf'):
                return -1
            total_cost += dist[s_idx][t_idx]

        return total_cost

