class Solution:
    def findMaximumNumber(self, k: int, x: int) -> int:
        def count_set_bits(num: int, x: int) -> int:
            """Count the set bits at positions that are multiples of x in the binary representation of num."""
            count = 0
            bit_position = 1
            while num > 0:
                if bit_position % x == 0 and num & 1:
                    count += 1
                num >>= 1
                bit_position += 1
            return count

        def is_valid(mid: int) -> bool:
            """Check if the sum of prices for all numbers from 1 to mid is less than or equal to k."""
            total_price = 0
            for i in range(1, mid + 1):
                total_price += count_set_bits(i, x)
                if total_price > k:
                    return False
            return True

        # Binary search to find the maximum num
        left, right = 1, 10**15
        while left < right:
            mid = (left + right + 1) // 2
            if is_valid(mid):
                left = mid
            else:
                right = mid - 1

        return left

