class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        # Convert changeIndices to 0-indexed
        changeIndices = [x - 1 for x in changeIndices]

        # Store the last occurrence of each index in changeIndices
        last_occurrence = {i: -1 for i in range(len(nums))}
        for s, idx in enumerate(changeIndices):
            last_occurrence[idx] = s

        # Helper function to check if all indices can be marked by second s
        def can_mark_all(s: int) -> bool:
            marked = [False] * len(nums)
            heap = []
            for i in range(s):
                idx = changeIndices[i]
                if not marked[idx]:
                    heapq.heappush(heap, (nums[idx], idx))
                if heap and heap[0][0] == 0:
                    _, idx = heapq.heappop(heap)
                    marked[idx] = True
                if heap and heap[0][0] > 0:
                    nums[heap[0][1]] -= 1
            return all(marked)

        # Binary search to find the earliest second
        left, right = 1, len(changeIndices)
        result = -1
        while left <= right:
            mid = (left + right) // 2
            if can_mark_all(mid):
                result = mid
                right = mid - 1
            else:
                left = mid + 1

        return result

