class Solution:
    def getSmallestString(self, s: str, k: int) -> str:
        def min_distance(a, b):
            return min((ord(a) - ord(b)) % 26, (ord(b) - ord(a)) % 26)

        def closest_char(c, k):
            if k >= min_distance(c, 'a'):
                return 'a'
            for i in range(1, 26):
                if min_distance(c, chr((ord(c) - ord('a') + i) % 26 + ord('a'))) <= k:
                    return chr((ord(c) - ord('a') + i) % 26 + ord('a'))
                if min_distance(c, chr((ord(c) - ord('a') - i) % 26 + ord('a'))) <= k:
                    return chr((ord(c) - ord('a') - i) % 26 + ord('a'))

        result = []
        for char in s:
            if k > 0:
                new_char = closest_char(char, k)
                result.append(new_char)
                k -= min_distance(char, new_char)
            else:
                result.append(char)

        return ''.join(result)

