class Solution:
    def numberOfStableArrays(self, zero: int, one: int, limit: int) -> int:
        MOD = 10**9 + 7
        n = zero + one
        dp = [[[0] * (one + 1) for _ in range(zero + 1)] for _ in range(n + 1)]
        dp[0][0][0] = 1

        for i in range(1, n + 1):
            for j in range(zero + 1):
                for k in range(one + 1):
                    if j > 0:
                        dp[i][j][k] = (dp[i][j][k] + dp[i-1][j-1][k]) % MOD
                    if k > 0:
                        dp[i][j][k] = (dp[i][j][k] + dp[i-1][j][k-1]) % MOD
                    if i > limit:
                        if j > limit:
                            dp[i][j][k] = (dp[i][j][k] - dp[i-limit-1][j-limit-1][k] + MOD) % MOD
                        if k > limit:
                            dp[i][j][k] = (dp[i][j][k] - dp[i-limit-1][j][k-limit-1] + MOD) % MOD

        return dp[n][zero][one]

