        def dfs(current_stair, jump):
            if current_stair == k:
                return 1
            if current_stair > k:
                return 0
            ways = 0
            if current_stair > 0:
                ways += dfs(current_stair - 1, jump)
            ways += dfs(current_stair + (1 << jump), jump + 1)
            return ways

