        while queue:
            (x, y), dist = queue.popleft()
            if (x, y) == b:
                return dist
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < H and 0 <= ny < W and not visited[nx][ny] and grid[nx][ny] != '#':
                    visited[nx][ny] = True
                    queue.append(((nx, ny), dist + 1))
        return float('inf')

    # Calculate the distances between all pairs of start, goal, and candies
    distances = {}
    for i in range(len(candies) + 2):
        for j in range(i + 1, len(candies) + 2):
            if i == 0:
                a = start
            elif i == 1:
                a = goal
            else:
                a = candies[i - 2]

            if j == 0:
                b = start
            elif j == 1:
                b = goal
            else:
                b = candies[j - 2]

            dist = bfs(a, b)
            distances[(a, b)] = dist
            distances[(b, a)] = dist

    # Function to check if a path is valid
    def is_valid(path):
        total_dist = 0
        for i in range(len(path) - 1):
            total_dist += distances[(path[i], path[i + 1])]
            if total_dist > T:
                return False
        return True

    # Generate all possible paths and find the maximum number of candies
    from itertools import permutations
    max_candies = -1
    for perm in permutations([start] + candies + [goal]):
        if perm[0] == start and perm[-1] == goal and is_valid(perm):
            max_candies = max(max_candies, len(perm) - 2)

    print(max_candies)

