    import sys
    input = sys.stdin.read
    data = input().split()

    X = int(data[0])
    Y = int(data[1])
    Z = int(data[2])
    S = data[3]

    # <think>
    # To solve this problem, we need to determine the minimum time required to type the string S.
    # We can break down the problem into segments where the Caps Lock state is consistent.
    # For each segment, we can calculate the cost of typing the segment in both states (Caps Lock on and off).
    # We then choose the cheaper option and add the cost of switching the Caps Lock state if necessary.
    # </think>

    def cost_of_segment(segment, is_caps_on):
        if is_caps_on:
            return sum(X if c == 'A' else Y for c in segment)
        else:
            return sum(X if c == 'a' else Y for c in segment)

    def min_cost_to_type(S):
        n = len(S)
        if n == 0:
            return 0

        # Initialize the dynamic programming table
        dp = [[float('inf')] * 2 for _ in range(n + 1)]
        dp[0][0] = 0  # Initial state with Caps Lock off

        for i in range(n):
            for is_caps_on in range(2):
                # Calculate the cost of the current segment
                segment_cost = cost_of_segment(S[i:i+1], is_caps_on)

                # Update the DP table for the next state
                dp[i + 1][is_caps_on] = min(dp[i + 1][is_caps_on], dp[i][is_caps_on] + segment_cost)

                # Consider the cost of switching the Caps Lock state
                dp[i + 1][1 - is_caps_on] = min(dp[i + 1][1 - is_caps_on], dp[i][is_caps_on] + Z + segment_cost)

        # The result is the minimum cost of typing the entire string in either state
        return min(dp[n][0], dp[n][1])

    result = min_cost_to_type(S)
    print(result)

