from collections import defaultdict, deque

def main():
    # Read input
    N, M = map(int, input().split())
    edges = [tuple(map(int, input().split())) for _ in range(M)]

    # Build the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Read the pairs (x_i, y_i) that should not be connected
    K = int(input())
    restrictions = [tuple(map(int, input().split())) for _ in range(K)]

    # Read the queries
    Q = int(input())
    queries = [tuple(map(int, input().split())) for _ in range(Q)]

    # Function to perform BFS and check if two nodes are connected
    def is_connected(graph, start, end):
        visited = set()
        queue = deque([start])
        while queue:
            node = queue.popleft()
            if node == end:
                return True
            if node not in visited:
                visited.add(node)
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        queue.append(neighbor)
        return False

    # Precompute the connected components
    components = {}
    component_id = 0
    visited = set()

    for node in range(1, N + 1):
        if node not in visited:
            component_id += 1
            queue = deque([node])
            while queue:
                current = queue.popleft()
                visited.add(current)
                components[current] = component_id
                for neighbor in graph[current]:
                    if neighbor not in visited:
                        queue.append(neighbor)

    # Check if the restrictions are already satisfied
    restriction_map = defaultdict(set)
    for x, y in restrictions:
        if components[x] == components[y]:
            print("No")
            continue
        restriction_map[components[x]].add(components[y])
        restriction_map[components[y]].add(components[x])

    # Process each query
    for p, q in queries:
        # If p and q are already in the same component, the graph is not good
        if components[p] == components[q]:
            print("No")
            continue

        # Check if adding the edge (p, q) violates any restriction
        if components[q] in restriction_map[components[p]] or components[p] in restriction_map[components[q]]:
            print("No")
        else:
            print("Yes")

