def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    T = int(data[1])
    M = int(data[2])
    incompatible_pairs = [(int(data[3*i+3])-1, int(data[3*i+4])-1) for i in range(M)]

    def is_valid_team(team, incompatible_pairs):
        for a, b in incompatible_pairs:
            if team[a] == team[b]:
                return False
        return True

    def count_ways(N, T, incompatible_pairs):
        count = 0
        for teams in permutations(range(T), N):
            if is_valid_team(teams, incompatible_pairs):
                count += 1
        return count // (T ** (N - T))

    result = count_ways(N, T, incompatible_pairs)
