import math

def euclidean_distance(x1, y1, x2, y2):
    return math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)

def main():
    # Read input
    N = int(input())
    checkpoints = [tuple(map(int, input().split())) for _ in range(N)]

    # Initialize the dynamic programming table
    dp = [float('inf')] * (1 << N)
    dp[0] = 0

    # Precompute distances between all pairs of checkpoints
    distances = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            distances[i][j] = euclidean_distance(checkpoints[i][0], checkpoints[i][1], checkpoints[j][0], checkpoints[j][1])

    # Function to calculate the penalty
    def penalty(C):
        return 2 ** (C - 1) if C > 0 else 0

    # Dynamic programming to find the minimum distance
    for mask in range(1 << N):
        for i in range(N):
            if mask & (1 << i):
                for j in range(N):
                    if not mask & (1 << j):
                        new_mask = mask | (1 << j)
                        skipped = bin(new_mask).count('1') - 2  # Number of checkpoints skipped
                        dp[new_mask] = min(dp[new_mask], dp[mask] + distances[i][j] + penalty(skipped))

    # Find the minimum distance from checkpoint 1 to checkpoint N
    final_mask = (1 << N) - 1
    min_distance = float('inf')
    for mask in range(1 << N):
        if mask & (1 << 0) and mask & (1 << (N - 1)):
            min_distance = min(min_distance, dp[mask])

    print(min_distance)

