        u = int(data[i]) - 1
        v = int(data[i + 1]) - 1
        w = int(data[i + 2])
        edges.append((u, v, w))

    # Function to check if a walk visits all vertices at least once
    def is_valid_walk(walk):
        visited = [False] * N
        for vertex in walk:
            visited[vertex] = True
        return all(visited)

    # Function to calculate the total weight of a walk
    def calculate_weight(walk):
        total_weight = 0
        for i in range(len(walk) - 1):
            u, v = walk[i], walk[i + 1]
            for edge in edges:
                if edge[0] == u and edge[1] == v:
                    total_weight += edge[2]
                    break
        return total_weight

    # Generate all permutations of vertices
    min_weight = float('inf')
    for perm in permutations(range(N)):
        if is_valid_walk(perm):
            weight = calculate_weight(perm)
            if weight < min_weight:
                min_weight = weight

    if min_weight == float('inf'):
        print("No")
    else:
        print(min_weight)

