from collections import defaultdict
import heapq

def main():
    # Read input
    N, M = map(int, input().split())
    trains = []
    for _ in range(M):
        l, d, k, c, A, B = map(int, input().split())
        for j in range(k):
            t = l + j * d
            trains.append((t, t + c, A, B))

    # Sort trains by departure time
    trains.sort()

    # Initialize the graph and the latest arrival times
    graph = defaultdict(list)
    latest_arrival = [-float('inf')] * (N + 1)
    latest_arrival[N] = float('inf')

    # Process each train
    for t, t_c, A, B in trains:
        if latest_arrival[A] >= t:
            latest_arrival[B] = max(latest_arrival[B], t_c)

    # Use a priority queue to find the latest arrival times for each station
    pq = [(-latest_arrival[N], N)]
    visited = set()

    while pq:
        time, station = heapq.heappop(pq)
        time = -time

        if station in visited:
            continue
        visited.add(station)

        for next_train in graph[station]:
            next_time, next_station = next_train
            if next_time <= time and latest_arrival[next_station] < time:
                latest_arrival[next_station] = time
                heapq.heappush(pq, (-time, next_station))

    # Output the results
    for i in range(1, N):
        if latest_arrival[i] == -float('inf'):
            print("Unreachable")
        else:
            print(latest_arrival[i])

