    L, R = map(int, input().split())

    def is_good_sequence(l, r):
        # A sequence is good if it can be represented as S(2^i * j, 2^i * (j+1))
        # This means (r - l) must be a power of 2 and l must be a multiple of (r - l)
        length = r - l
        return (length & (length - 1) == 0) and (l % length == 0)

    def find_next_good_sequence(l, r):
        # Find the largest good sequence starting at l and ending before r
        for length in range((r - l).bit_length(), 0, -1):
            if is_good_sequence(l, l + (1 << length)):
                return l, l + (1 << length)
        return l, l + 1  # Fallback to a sequence of length 1

    result = []
    while L < R:
        l, r = find_next_good_sequence(L, R)
        result.append((l, r))
        L = r

    print(len(result))
    for l, r in result:
        print(l, r)

