import sys
from collections import defaultdict
from heapq import heappop, heappush

def main():
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    M = int(data[1])
    index = 2
    edges = []
    parent = list(range(N + 1))
    rank = [0] * (N + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1

    for _ in range(M):
        K = int(data[index])
        C = int(data[index + 1])
        vertices = list(map(int, data[index + 2:index + 2 + K]))
        for i in range(len(vertices)):
            for j in range(i + 1, len(vertices)):
                edges.append((C, vertices[i], vertices[j]))
        index += 2 + K

    edges.sort()

    total_weight = 0
    for C, u, v in edges:
        if find(u) != find(v):
            union(u, v)
            total_weight += C

    connected_components = set()
    for i in range(1, N + 1):
        connected_components.add(find(i))

    if len(connected_components) > 1:
        print(-1)
    else:
        print(total_weight)

if __name__ == "__main__":
    main()
